<div class="customer-modal-backdrop stock-form-backdrop" role="presentation"><section class="estimate-side-panel stock-side-panel" role="dialog" aria-modal="true"><div class="estimate-panel-header"><div><h2>Add Stock Purchase</h2><span>Receive stock from a supplier</span></div><a href="index.php?page=admin&amp;section=stock-purchases">&times;</a></div><div class="estimate-panel-body"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=stock-purchases-add"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="estimate-form-section"><div class="row g-3"><div class="col-6"><label class="form-label">Supplier</label><select class="form-select" name="supplier_id"><option value="0">No supplier</option><?php foreach($suppliers as $supplier): ?><option value="<?= (int)$supplier['id'] ?>"><?= e($supplier['name'].' ('.$supplier['supplier_code'].')') ?></option><?php endforeach; ?></select></div><div class="col-6"><label class="form-label">Purchase Date *</label><input class="form-control" type="date" name="purchase_date" value="<?= e($input['purchase_date']) ?>" required></div></div></div><div class="estimate-form-section"><div class="estimate-items-heading"><h3>Purchase Items</h3><button type="button" class="btn btn-outline-danger btn-sm" id="add-purchase-item">+ Add Item</button></div><div id="purchase-items"><div class="purchase-item-row"><select class="form-select" name="items[0][stock_item_id]" required><option value="">Select stock item</option><?php foreach($stockOptions as $item): ?><option value="<?= (int)$item['id'] ?>"><?= e($item['part_code'].' - '.$item['part_name']) ?></option><?php endforeach; ?></select><input class="form-control" type="number" min="0.01" step="0.01" name="items[0][quantity]" value="1"><input class="form-control" type="number" min="0" step="0.01" name="items[0][unit_cost]" value="0"><button type="button" class="estimate-remove-item">&times;</button></div></div><small class="bay-field-hint">Saving a purchase automatically increases the selected stock quantities.</small></div><div class="estimate-form-section"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3"></textarea></div><div class="estimate-form-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-purchases">Cancel</a><button class="btn btn-danger" type="submit">Save Purchase</button></div></form></div></section></div>
<script>document.addEventListener('DOMContentLoaded',function(){const box=document.getElementById('purchase-items'),add=document.getElementById('add-purchase-item');let n=1;add.addEventListener('click',function(){const row=box.querySelector('.purchase-item-row').cloneNode(true);row.querySelectorAll('input').forEach(function(i){i.value=i.name.includes('quantity')?'1':'0';i.name=i.name.replace(/items\[\d+\]/,'items['+n+']');});const select=row.querySelector('select');select.value='';select.name=select.name.replace(/items\[\d+\]/,'items['+n+']');row.querySelector('.estimate-remove-item').onclick=function(){row.remove();};box.appendChild(row);n++;});box.querySelector('.estimate-remove-item').onclick=function(){box.querySelector('.purchase-item-row').remove();};});</script>
